			if (state.type != Value.Type.Literal) {
				return true;
			}
			if (payload instanceof LmdbLiteral literal) {
				return isPrepared(literal.getDatatype());
			}
			if (payload instanceof SimpleLiteral literal) {
				return isPrepared(literal.getDatatype());
			}
			if (payload instanceof Literal literal) {
				return isPrepared(literal.getDatatype());
			}
